// Обычный редактируемый пример привязки к своему API; только два PUBLIC сценария.
class TaskBinding{static UnsupportedOperationException pending(){return new UnsupportedOperationException("Привязка примера ещё не подготовлена");}static Object vehicle(int p,int f,int m){throw pending();}static Object truck(int p,int f,int m,int c){throw pending();}static int cargo(Object x){throw pending();}static void cargo(Object x,int c){throw pending();}static int[] state(Object x){throw pending();}static int range(Object x){throw pending();}static double fuel(Object x,int miles){throw pending();}static void setFuel(Object x,int f){throw pending();}}
